const D = { energy: .55, scale: 1, density: .55, speed: 1, shaft: .6, damp: .55, hue: 30, x: .5, y: .66, style: 'limestone', act: 'flow', seed: 0, alpha: 1 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const u = Math.min(width, height);
const fr = i => { const q = Math.sin(i * 127.1 + P.seed * 311.7) * 43758.5453; return q - Math.floor(q); };
const hw = h => ((h % 360) + 360) % 360;
const ho = P.hue - 30;
const L3 = (a, b, f) => [a[0] + (b[0]-a[0])*f, a[1] + (b[1]-a[1])*f, a[2] + (b[2]-a[2])*f];
const sh = c => [hw(c[0] + ho), c[1], c[2]];

const STY = {
  // warm limestone cave, amber shaft, teal river
  limestone: { far:[36,50,40], dark:[28,40,8], rock:[26,34,16], rockL:[32,40,32], drip:[30,30,58],
               water:[186,44,26], shaftC:[44,60,90], spark:[40,30,90], grain:16, uv:0, lineOnly:0 },
  // white gypsum crystals, cool, glittering
  gypsum:    { far:[196,26,44], dark:[210,30,7], rock:[206,20,18], rockL:[200,16,40], drip:[200,20,66],
               water:[200,40,24], shaftC:[54,30,92], spark:[196,10,99], grain:14, uv:0, lineOnly:0 },
  // ABSTRACTED UV fluorescence: minerals glowing on near-black
  blacklight:{ far:[280,60,20], dark:[268,60,5], rock:[272,50,10], rockL:[286,44,22], drip:[150,70,70],
               water:[260,60,16], shaftC:[130,80,80], spark:[110,90,99], grain:8, uv:1, lineOnly:0 },
  // ABSTRACTED cyan cave-survey blueprint
  blueprint: { far:[196,44,28], dark:[204,54,8], rock:[200,40,16], rockL:[190,30,40], drip:[190,30,70],
               water:[196,44,22], shaftC:[186,40,70], spark:[186,26,92], grain:5, uv:0, lineOnly:1 },
  // ABSTRACTED sumi ink tonal wash
  ink:       { far:[30,5,50], dark:[30,8,7], rock:[30,9,16], rockL:[30,6,36], drip:[30,4,60],
               water:[30,5,40], shaftC:[30,6,80], spark:[30,3,90], grain:28, uv:0, lineOnly:0 }
};
const st = STY[P.style] || STY.limestone;

const en = Math.max(0, Math.min(1, P.energy));
const wy = height * P.y;                          // near waterline (foreground)
const vx = width * (.42 + P.x * .16);             // vanishing point x
const vy = height * (.34 + (1 - P.y) * .2);       // vanishing point y (far reach)
const key = width + 'x' + height + '|' + P.style + '|' + P.seed + '|' + Math.round(P.hue) + '|' + P.scale.toFixed(2) + '|' + P.density.toFixed(2) + '|' + P.y.toFixed(3) + '|' + P.x.toFixed(3);

if (!S.cave || S.key !== key) {
  const W = Math.max(2, Math.ceil(width)), H = Math.max(2, Math.ceil(height));
  const mk = (w, h) => { const g = createGraphics(Math.max(2, Math.ceil(w)), Math.max(2, Math.ceil(h))); g.colorMode(g.HSB, 360, 100, 100, 100); return g; };
  if (S.cave) { S.cave.remove(); }
  S.cave = mk(W, H);
  const g = S.cave; g.noStroke();
  const farC = sh(st.far), darkC = sh(st.dark), rockC = sh(st.rock), rockL = sh(st.rockL), sparkC = sh(st.spark);

  // radial darkness: bright far reach at the vanishing point, black at the frame edges
  // (concentric ellipses, cheap + smooth — not a per-pixel loop)
  g.fill(darkC[0], darkC[1], darkC[2]); g.rect(0, 0, W, H);
  const diag = Math.hypot(W, H);
  for (let s = 56; s >= 0; s--) {
    const f = s / 56;                             // 1 outer(dark) .. 0 centre(bright)
    const c = L3(farC, darkC, Math.pow(f, .8));
    g.fill(c[0], c[1], c[2]);
    g.ellipse(vx, vy, diag * 1.5 * f + u * .02, diag * 1.15 * f + u * .02);
  }

  // cavern rock: left and right masses converging toward the vanishing point (mouth of the passage)
  const mouthW = u * (.16 + P.density * .06);
  for (let side = -1; side <= 1; side += 2) {
    g.noStroke(); g.fill(rockC[0], rockC[1], rockC[2], 100);
    g.beginShape();
    const outer = side < 0 ? -u * .05 : W + u * .05;
    g.vertex(outer, -10); g.vertex(outer, H + 10);
    // inner edge sweeps from foreground frame to the mouth at the vanishing point
    for (let f = 1; f >= 0; f -= .05) {
      const ex = L3([outer, 0, 0], [vx + side * mouthW, 0, 0], f)[0]
               + side * Math.sin(f * 9 + fr(side + 2) * 6.3) * u * .03 * (f)
               + side * Math.sin(f * 21) * u * .012;
      const ey = L3([H + 10, 0, 0], [vy, 0, 0], f)[0];
      g.vertex(ex, ey);
    }
    g.endShape(g.CLOSE);
    // flowstone drapes + hatch texture
    if (!st.lineOnly) {
      for (let d = 0; d < Math.floor(10 + P.density * 12); d++) {
        const f = fr(d * 3 + side * 40 + 1);
        const dx = L3([outer, 0, 0], [vx + side * mouthW, 0, 0], f)[0] + side * u * .02;
        const dy = L3([H, 0, 0], [vy, 0, 0], f)[0];
        const c = L3(rockL, rockC, fr(d));
        g.strokeWeight(Math.max(.6, u * .003 * (1 - f * .6))); g.stroke(c[0], c[1], Math.max(2, c[2]), 40);
        g.noFill(); g.beginShape();
        for (let t = 0; t <= 1; t += .2) g.vertex(dx + side * t * u * .04 * (1 - f), dy - u * .1 * (1 - f) + t * u * .12 * (1 - f * .5));
        g.endShape(); g.noStroke();
      }
    }
    // gypsum / crystal sparkle on the walls
    for (let sp = 0; sp < Math.floor(20 + P.density * 30); sp++) {
      const f = fr(sp * 3 + side * 60 + 1);
      const sx = L3([outer, 0, 0], [vx + side * mouthW, 0, 0], f)[0] + side * fr(sp * 3 + 2) * u * .06;
      const sy = L3([H, 0, 0], [vy, 0, 0], fr(sp * 3 + 3))[0] + (fr(sp) - .5) * u * .3;
      g.fill(sparkC[0], sparkC[1] * (st.uv ? 1 : .4), sparkC[2], (st.uv ? 40 : 22) * (1 - f * .5));
      g.ellipse(sx, sy, u * .003 * (1 - f * .5), u * .003 * (1 - f * .5));
    }
  }

  // roof stalactites hanging along the top, receding toward the vanishing point
  const nst = Math.floor(14 + P.density * 20);
  for (let i = 0; i < nst; i++) {
    const f = fr(i * 3 + 71);                       // 0 near, 1 far
    const rx = L3([fr(i * 3 + 72) * W, 0, 0], [vx, 0, 0], f)[0];
    const ry = L3([-u * .02, 0, 0], [vy - u * .03, 0, 0], f)[0];
    const sl = u * (.05 + fr(i * 3 + 73) * .14) * (1 - f * .7) * P.scale;
    const sw = sl * (.1 + fr(i * 3 + 74) * .1);
    const c = L3(rockL, sh(st.dark), .3 + f * .4);
    if (st.lineOnly) { g.stroke(c[0], c[1], c[2], 60); g.strokeWeight(1); g.line(rx, ry, rx, ry + sl); g.noStroke(); }
    else { g.fill(c[0], c[1], c[2], 100); g.triangle(rx - sw, ry, rx + sw, ry, rx + (fr(i) - .5) * sw, ry + sl); }
  }
  S.vx = vx; S.vy = vy;
  S.key = key;
}

// ---------------- act ----------------
const sec = ((Math.floor(K.section) % 6) + 6) % 6;
const ACT = { flow: { flow: 1, drip: 1, damp: 1 }, flood: { flow: 1.5, drip: 1.6, damp: 1 + sec * .04 }, still: { flow: .5, drip: .5, damp: 1.2 } };
const act = ACT[P.act] || ACT.flow;
const damp = Math.max(.1, Math.min(1.3, P.damp * act.damp));

noStroke();
image(S.cave, 0, 0);

// ---------------- the river: a bright band widening from the vanishing point to the foreground ----------------
const waterC = sh(st.water), shaftC = sh(st.shaftC), sparkC = sh(st.spark);
const riverTop = S.vy + u * .02;
const halfNear = u * (.16 + P.density * .06) * P.scale;
noStroke();
fill(waterC[0], waterC[1], waterC[2], 100);
beginShape();
vertex(S.vx - u * .01, riverTop); vertex(S.vx + u * .01, riverTop);
vertex(width * .5 + halfNear, height + 10); vertex(width * .5 - halfNear, height + 10);
endShape(CLOSE);

// flow shimmer + reflection of the shaft on the water
noFill();
const nf = Math.floor(14 + P.density * 18);
for (let i = 0; i < nf; i++) {
  const f = Math.pow((i + .5) / nf, 1.6);
  const yy = riverTop + f * (height - riverTop);
  const cx = L3([S.vx, 0, 0], [width * .5, 0, 0], f)[0];
  const hwd = L3([u * .01, 0, 0], [halfNear, 0, 0], f)[0];
  const ph = K.t * (.4 + f * .9) * P.speed * act.flow;
  strokeWeight(Math.max(.6, u * .0018 * (.3 + f * 2)));
  stroke(waterC[0], waterC[1] * .6, Math.min(99, waterC[2] + 16 + 24 * f), (20 + 30 * f) * (.4 + en));
  beginShape();
  for (let t = -1; t <= 1; t += .1) {
    const wob = Math.sin(t * 6 + ph) * u * .004 * (.3 + f) + Math.sin(t * 13 - ph * 1.4) * u * .002;
    vertex(cx + t * hwd, yy + wob);
  }
  endShape();
}
noStroke();

// ---------------- the light shaft from the skylight, raking down to the water ----------------
if (!st.lineOnly) {
  blendMode(ADD);
  const sx = S.vx + Math.sin(K.t * .05) * u * .01;
  const br = P.shaft * (.6 + .4 * Math.sin(K.t * .17 + 1)) * (.7 + .3 * K.swell) + A.mid * .12;
  const top = -u * .05, bottom = riverTop + u * .1;
  for (let s = 0; s < 3; s++) {
    const wsh = u * (.02 + s * .04) * (.6 + P.shaft);
    fill(shaftC[0], shaftC[1] * (1 - s * .2), shaftC[2], (2.6 + 7 * br * en) * (1 - s * .25));
    beginShape();
    vertex(sx - wsh * .2, top); vertex(sx + wsh * .2, top);
    vertex(sx + wsh, bottom); vertex(sx - wsh, bottom);
    endShape(CLOSE);
  }
  // the pool of light where the shaft hits the water
  fill(shaftC[0], shaftC[1] * .5, shaftC[2], (6 + 14 * br * en));
  ellipse(sx, riverTop + u * .05, u * .14 * (.6 + P.shaft), u * .03);
  blendMode(BLEND);
}

// ---------------- dust motes turning in the shaft (motion floor) ----------------
blendMode(ADD);
const nm = Math.floor(24 + P.density * 40);
for (let i = 0; i < nm; i++) {
  const life = ((K.t * (.015 + fr(i * 3 + 101) * .03) * P.speed + fr(i * 3 + 102)) % 1);
  const mxp = S.vx + (fr(i * 3 + 103) - .5) * u * .2 + Math.sin(K.t * (.2 + fr(i) * .3) + i) * u * .03;
  const myp = life * (riverTop + u * .1);
  const near = fr(i * 3 + 104);
  fill(sparkC[0], sparkC[1] * .4, sparkC[2], (6 + 16 * en) * (.3 + near) * (1 - Math.abs(life - .5)));
  ellipse(mxp, myp, u * .002 * (.5 + near), u * .002 * (.5 + near));
}
blendMode(BLEND);

// ---------------- drips falling from the roof into the river ----------------
if (!st.lineOnly) {
  const dripC = sh(st.drip);
  const nd = Math.floor((4 + P.density * 8) * act.drip);
  for (let i = 0; i < nd; i++) {
    const dx = fr(i * 3 + 111) * width;
    const life = ((K.t * (.4 + fr(i * 3 + 112)) * P.speed + fr(i * 3 + 113)) % 1);
    const dy = life * height;
    fill(dripC[0], dripC[1] * .6, Math.min(99, dripC[2]), 50 * (1 - life * .4) * damp);
    ellipse(dx, dy, u * .003, u * .012);
    if (life > .92) { // ripple where it lands
      noFill(); strokeWeight(u * .001); stroke(dripC[0], dripC[1] * .5, dripC[2], 40 * (1 - life) * 12);
      ellipse(dx, dy, u * .02, u * .006); noStroke();
    }
  }
}

// grain, vignette, alpha
if (st.grain > 6) {
  const ng2 = Math.floor(st.grain * 5);
  for (let i = 0; i < ng2; i++) {
    const gx = ((fr(i * 3 + 401) * width) + Math.sin(K.t * .01 + i) * u * .002 + width) % width;
    const gy = fr(i * 3 + 402) * height;
    fill(st.dark[0], st.dark[1] * .4, fr(i * 3 + 403) > .5 ? 70 : 4, 3 + fr(i) * 5);
    rect(gx, gy, u * .0016, u * .0016);
  }
}
for (let i = 0; i < 6; i++) {
  noFill(); strokeWeight(u * .06);
  stroke(sh(st.dark)[0], st.dark[1], 3, 26 * (1 - i * .15));
  rect(-u * .03 + i * u * .03, -u * .03 + i * u * .03, width + u * .06 - i * u * .06, height + u * .06 - i * u * .06);
}
noStroke();
if (P.alpha < 1) { fill(sh(st.dark)[0], st.dark[1] * .5, 3, (1 - P.alpha) * 100); rect(0, 0, width, height); }
blendMode(BLEND);
drawingContext.shadowBlur = 0;

// RESCUE2: strong drifting luminous band sweeping the frame (guaranteed large-area motion)
{ const dcR=drawingContext; dcR.save();
  const bx=width*((K.t*0.045)%1.3-0.15);
  const g2=dcR.createLinearGradient(bx-width*0.25,0,bx+width*0.25,0);
  g2.addColorStop(0,color(45,20,80,0).toString());
  g2.addColorStop(0.5,color(45,25,95,38*((P.alpha==null?100:P.alpha))/100).toString());
  g2.addColorStop(1,color(45,20,80,0).toString());
  dcR.fillStyle=g2; dcR.fillRect(0,0,width,height); dcR.restore(); }
